from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); mark=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==0 and (nx,ny) not in seen: seen.add((nx,ny));q.append((nx,ny))
   comps.append(comp)
   if len(comp)>1:mark.update(comp)
out=[[8 if (r,c) in mark else v for c,v in enumerate(row)] for r,row in enumerate(grid)]
